  /* ============================================================
   * 豆包v165：科技类个人装备再识别 + 缺数值装备自动派生
   * 大表里一部分「可穿戴的个人武器/防具」被归到 misc（复合弓、龙鳞甲、防化服、女武神/弑神装甲…），
   * 且多数没写 stats。这里把它们识别出来、按价格补一套兜底数值，保证：买到 → 能装入装备槽 → 进战斗有效果。
   * 巨型 / 载具 / 机甲 / 飞船 / 固定设施不在此列（归 vehicle/large，由 WK.Items.useGadget 给场景限制提示）。
   * 数值为对数平滑兜底（刻意不超同价位精调装备）；要精调时直接在大表 stats 写死即可被优先采用。
   * ============================================================ */
  WK.TECH_LARGE_RE = /机甲|机器人|战车|坦克|飞车|巴士|卡车|装甲输送|步战|步兵|直升机|无人机|滑板|摩托车|自行车|推进器|潜水艇|飞船|护卫舰|驱逐舰|启航号|太阳号|日龙号|威尔特尔|薇尔洁|异度装甲|天之志雷马|Rahxephon|任意门|虫洞|力场|发生器|监视器|星球监视|导弹|火箭筒|核弹|炸弹|地雷|腰带|人生重来|查拉图|等离子切割炮/;
  WK.techEquipGuess = function (it) {
    if (!it || it.equip) return null;
    const n = it.name || "";
    const large = WK.TECH_LARGE_RE.test(n);
    if (large) return null;
    // 弓（复合弓等）
    if (/弓/.test(n)) return { kind: "weapon", slot: "weapon", wepType: "bow", type: "bow" };
    // 个人防具：甲 / 盾 / 防护服 / 作战服 / 飞鼠装 / 女武神 / 弑神 等
    if (/(装甲|护甲|防弹|防化|防护服|作战服|飞鼠|龙鳞|盾|军团服|女武神|弑神)/.test(n))
      return { kind: "armor", slot: "armor" };
    // 漏标的个人枪械（高置信才判，避免误伤）
    if (/黑百合之吻/.test(n)) return { kind: "weapon", slot: "weapon", wepType: "ranged", type: "firearm" };
    return null;
  };
  WK.deriveEquipStats = function (slotKey, it) {
    const price = Math.max(1, Number(it.price) || 0);
    const L = Math.log2(price + 1);   // 对数档：1点≈1 / 50点≈5.7 / 1000点≈10 / 16000点≈14
    if (slotKey === "ranged" || slotKey === "bow") {
      const dmgMax = Math.round(12 + L * 8.5);
      return { atk: Math.max(2, Math.round(L * 0.8)), dmgMin: Math.round(dmgMax * 0.45), dmgMax: dmgMax, hit: 0.04, crit: 0.03 };
    }
    if (slotKey === "melee") return { atk: Math.round(3 + L * 2.4), hit: 0.02, crit: 0.03 };
    return { armor: Math.max(1, Math.round(1 + L * 1.1)), maxHp: Math.round(2 + L * 3.5) }; // armor
  };

  WK.catalogInstall = function () {
    // 豆包v175：口述/DIY 向血统（需自行设定、咨询主神、自己组牌）无法在文字游戏量化，
    // 从兑换目录与血统库一并下架——搜索不到、卡片不渲染、ITEM_DEF 不建、无法购买。filter 幂等可重复调用。
    // 豆包v178：炉石系附属道具（炉石之心-一次性卡包/普通/稀有卡牌…）属同一口述向玩法，一并下架，避免血统删了卡包还在卖。
    if (WK.Blood && WK.Blood.REMOVED_BLOODS && WK.CATALOG) {
      const rm = WK.Blood.REMOVED_BLOODS;
      if (WK.CATALOG.aux) WK.CATALOG.aux = WK.CATALOG.aux.filter(function (it) {
        if (!it || !it.name) return true;
        if (rm.indexOf(it.name) >= 0) return false;
        if (/^炉石之心/.test(it.name)) return false;
        return true;
      });
      if (WK.BLOOD_DB) rm.forEach(function (nm) { delete WK.BLOOD_DB[nm]; });
    }
    const cats = ["tech", "magic", "aux", "fun"];
    cats.forEach(function (ck) {
      const list = (WK.CATALOG && WK.CATALOG[ck]) || [];
      list.forEach(function (it) {
        if (!it || !it.id) return;
        if (WK.ITEM_DEF[it.id]) return; // 手写优先
        const def = {
          name: it.name,
          bulk: it.bulk != null ? it.bulk : 1,
          kind: it.equip
            ? (it.wepType === "melee" || it.wepType === "ranged" ? "weapon"
              : (it.slot === "armor" ? "armor" : "equip"))
            : (it.kind_item === "ammo" || it.kind === "ammo" || it.kind === "arrow" || it.kind === "ammo_ench" || it.kind === "ammo_arrow" ? "ammo"
              : it.kind_item === "throw" || it.kind === "throw" ? "throw"
              : it.kind_item === "scroll" || it.kind === "scroll" ? "scroll"
              : it.kind_item === "heal" || it.kind === "heal" ? "heal"
              : it.kind_item === "energy" || it.kind === "energy" ? "potion"
              : it.kind_item === "food" || it.kind === "food" ? "food"
              : it.kind === "charm" ? "charm"   // 豆包v167：护身符/符咒（对鬼怪用的对策卡），单独保留类型
              : it.kind === "vehicle" ? "vehicle"
              : it.kind === "tool" ? "tool"
              : "misc"),
          bind: it.bind || (it.equip ? "equip" : "item"),
          desc: it.desc || ""
        };
        // 豆包v165：科技类把被归到 misc 的个人武器/防具捞回来（买到即可装备）
        let guessed = null;
        if (ck === "tech" && !it.equip) {
          guessed = WK.techEquipGuess(it);
          if (guessed) {
            it.equip = true;
            if (guessed.slot) { it.slot = guessed.slot; def.slot = guessed.slot; }
            if (guessed.wepType) { it.wepType = guessed.wepType; def.wepType = guessed.wepType; }
            if (guessed.type) { it.type = guessed.type; def.type = guessed.type; }
            def.kind = guessed.kind;
            def.bind = "equip";
          }
        }
        if (it.slot) def.slot = it.slot;
        if (it.wepType) def.wepType = it.wepType;
        if (it.type) def.type = it.type;
        if (it.stats) def.stats = it.stats;
        // 豆包v165：个人装备缺 stats 时按价格自动派生兜底数值（大表显式 stats 优先，不会走到这）
        if (def.bind === "equip" && !def.stats) {
          const sk = def.kind === "armor" ? "armor"
            : (def.wepType === "bow" ? "bow" : def.wepType === "ranged" || def.type === "firearm" ? "ranged" : "melee");
          def.stats = WK.deriveEquipStats(sk, it);
          def.derived = true;   // 标记为自动派生，便于后续在面板/调试中辨认
        }
        if (it.ammoTag) def.ammoTag = it.ammoTag;
        // 豆包v167：附魔弹等级（1–6，决定主动「附魔一击」威力）与符咒对策标记，原样落库供战斗读取
        if (it.enchLv) def.enchLv = it.enchLv;
        if (it.kind === "charm") { def.kind = "charm"; def.disposable = /一次性/.test(it.name || ""); }
        if (it.infinite) def.infinite = true;
        if (it.priceMul) def.priceMul = it.priceMul;
        if (it.consumable) def.consumable = true;
        // 豆包v165：科技表中部分医疗道具没写 heal（被归到 tool/misc），按名称补回复量，
        // 使其统一走下方 v164 的医疗桥接（战斗内/外都能用、走同一 CD）。「无限能源」款标 infinite，不被消耗。
        if (ck === "tech" && (!it.stats || it.stats.heal == null) && /医疗|治疗|急救|痊愈/.test(it.name || "")) {
          it.stats = it.stats || {};
          if (/纳米级医疗包/.test(it.name)) it.stats.heal = 150;
          else if (/无限能源医疗/.test(it.name)) { it.stats.heal = 80; it.infinite = true; }
          else it.stats.heal = 80;
          // 注入可能发生在 def.stats 赋值之后（原本无 stats 的物品），这里把新建的 it.stats 同步回 def，
          // 否则背包非战使用读 d.stats.heal 会落空。kind 归 heal，背包/战斗识别保持一致。
          def.stats = it.stats; def.kind = "heal";
        }
        // 豆包v164【P3 接缝修复】大表医疗/回复品原本被归成 misc、固定点数 stats.heal 与战斗系统
        // 的比例结构 def.heal.hp 对不上，导致「能买却战斗内用不了」。此处把生命/体力回复桥接成
        // def.heal={flatHp/flatSta} 并打开 battleUse，进入战斗道具栏（battle._battleHeal 已支持固定值）。
        // 纯血统能量药水（仅 stats.energy）第一期不接入战斗道具，能量靠战斗内回复系统恢复。
        if (it.stats && (it.stats.heal != null || it.stats.stamina != null || it.stats.sta != null)) {
          const hh = {};
          if (it.stats.heal != null) hh.flatHp = it.stats.heal;
          if (it.stats.stamina != null) hh.flatSta = it.stats.stamina;
          else if (it.stats.sta != null) hh.flatSta = it.stats.sta;
          def.heal = hh;
          def.battleUse = true;
        }
        // 豆包v169：传说魔法类二次归类（召唤模型/法杖/射影机/卷轴/丹药…噪声修正），必须在落库前
        if (ck === "magic" && WK.magicFinish) WK.magicFinish(it, def);
        // 豆包v170：娱乐类二次归类（整容药水/整蛊/吃喝/一立方米整人货…），点「使用/赠送」必有有趣反馈
        if (ck === "fun" && WK.funFinish) WK.funFinish(it, def);
        // 豆包v172：辅助类分流（血统标记 / 药水道具 / 各体系技能生成 SKILL_DEF）
        if (ck === "aux" && WK.auxFinish) WK.auxFinish(it, def);
        WK.ITEM_DEF[it.id] = def;
      });
    });

    /* 豆包v177：防御护符改为【耐久护盾】道具（旧版只是 +maxHp/未被消费的死字段）。
       覆盖在落库之后，强制以这里为准：
       · 一次性恶意护身符＝消耗品，使用即凝结 500 点辟邪护罩，护罩耗尽/本次使用后道具即消耗；
       · 恶意护身符＝可反复充能的常驻护符（800 点），恐怖片内不回复，回主神「全身修复」充满；
       · 冰晶护盾＝装备型盾牌（仍 +68 护甲），穿戴期间提供 427 点可充能耐久护罩，擅御火焰。
       （殉道护符=法术增伤、护身符=自毁反击，属输出向，不改为盾。） */
    const _sh = {
      m_c29556997: { name:"一次性恶意护身符", kind:"charm", bind:"item", bulk:0, consumable:true, battleUse:true,
        shieldId:"m_c29556997", kind_item:"charm",
        desc:"恶灵袭击时会提前燃烧警告。捏碎护身符凝结一层辟邪护罩，可吸收 500 点伤害；护罩只此一次，耗尽即消散（对灵体同样有效）。" },
      m_c60759910: { name:"恶意护身符", kind:"charm", bind:"item", bulk:0, unique:true, battleUse:true,
        shieldId:"m_c60759910", kind_item:"charm",
        desc:"护身符内封存着恶意凝成的能量。激发后形成可吸收 800 点伤害的护罩；能量在恐怖片内不会自行恢复，需回到主神空间「全身修复」重新充满。可反复使用、不会损毁。" }
    };
    Object.keys(_sh).forEach(function(id){ if(WK.ITEM_DEF[id]) WK.ITEM_DEF[id] = Object.assign({}, WK.ITEM_DEF[id], _sh[id]); });
    if (WK.ITEM_DEF.m_c36866240) {
      WK.ITEM_DEF.m_c36866240 = Object.assign({}, WK.ITEM_DEF.m_c36866240, {
        equipShield:true, kind:"armor", bind:"equip", slot:"accessory", equip:true,
        stats:{ armor:68 },   // 旧 shield:427 死字段移除，改由 p.shields 耐久层承接（回主神充能）
        desc:"由冰晶凝成的盾牌，佩戴期间维持一层 427 点的冰晶护罩，擅御火焰（火焰伤害由它优先抵消、效率更高）；护罩碎裂后需回主神空间「全身修复」重新凝结。另提供 68 点护甲。"
      });
    }
  };

  /* ============================================================
   豆包v177：耐久护盾（独立于生命值的吸收层）
   ------------------------------------------------------------
   · 玩家身上可同时挂多层护盾 p.shields = [{key,name,max,cur,rechargeable,equip}]
   · 受伤时先扣护盾（在血统免疫判定之后、血族保命之前），扣穿才掉血；
   · 一次性护符：激活即消耗道具，护罩 cur 归零后该层直接消失；
   · 可充能护符 / 冰晶护盾：cur 归零后层保留但失效，回主神「全身修复」(recharge) 充满；
   · 冰晶护盾是装备型，仅在穿戴中参与抵扣，且对火焰伤害优先、1 点护罩抵 1.5 点火伤。
   老存档无 p.shields 时惰性初始化为 []。
   ============================================================ */
  WK.Shield = {
    CONSUME: {
      m_c29556997: { name:"辟邪护罩", max:500 },
      m_c60759910: { name:"恶意护罩", max:800 }
    },
    layers(){
      const p = WK.P; if (!p) return [];
      if (!Array.isArray(p.shields)) p.shields = [];
      this._syncEquip(p);
      return p.shields;
    },
    /* 冰晶护盾：穿戴中且还没有层时补一层（满额）；卸下后层保留但 _active=false，回主神仍可充 */
    _syncEquip(p){
      const wornId = this._wornIceId(p);
      const has = p.shields.some(l => l.key === "m_c36866240");
      if (wornId && !has) p.shields.push({ key:"m_c36866240", name:"冰晶护盾", max:427, cur:427, rechargeable:true, equip:true });
    },
    _wornIceId(p){
      const eq = (p && p.equip) || {};
      return Object.keys(eq).some(k => eq[k] === "m_c36866240") ? "m_c36866240" : null;
    },
    _active(l){
      if (!l.equip) return true;
      return this._wornIceId(WK.P) === l.key;
    },
    /* 激活一个护符道具。返回 {ok,status,msg}；status: 'on' 新激活 / 'exists' 护罩仍在 / 'no'*/
    activate(id){
      const p = WK.P, cfg = this.CONSUME[id];
      if (!cfg) return { ok:false, status:"no", msg:"这件道具无法凝结护罩。" };
      const ls = this.layers();
      const ex = ls.find(l => l.key === id && l.cur > 0);
      if (ex) return { ok:false, status:"exists", msg:"「"+cfg.name+"」仍在，剩余 "+Math.round(ex.cur)+" 点，无需重复激发。" };
      // 可充能护符 cur 已耗尽但层还在 → 提示回主神，不能在恐怖片内重新充
      const drained = ls.find(l => l.key === id && l.rechargeable && l.cur <= 0);
      if (drained) return { ok:false, status:"drained", msg:"护符内的能量已经耗尽，需回到主神空间全身修复后才能重新充满。" };
      p.shields.push({ key:id, name:cfg.name, max:cfg.max, cur:cfg.max, rechargeable:id==="m_c60759910" });
      return { ok:true, status:"on", msg:"「"+cfg.name+"」凝形，笼罩周身，可吸收 "+cfg.max+" 点伤害。" };
    },
    /* 当前生效护盾总值（HUD 用） */
    total(){ return this.layers().filter(l => l.cur > 0 && this._active(l)).reduce((s,l)=>s+l.cur,0); },
    /* 受伤抵扣：返回 {dmg:扣盾后剩余伤害, absorbed}。fire=本次是否火焰伤害 */
    absorb(dmg, foe){
      const p = WK.P;
      let ls = this.layers().filter(l => l.cur > 0 && this._active(l));
      if (!ls.length) return { dmg:dmg, absorbed:0 };
      const isFire = !!(foe && (foe.element === "fire" || foe.fire || (foe.def && (foe.def.element==="fire"||foe.def.fire))));
      // 火焰伤害：冰晶护盾优先；其余按数组顺序（先激发的在外层）
      if (isFire) ls = ls.slice().sort((a,b)=>((b.key==="m_c36866240")?1:0)-((a.key==="m_c36866240")?1:0));
      let left = dmg, absorbed = 0;
      for (const l of ls){
        if (left <= 0) break;
        const eff = (isFire && l.key === "m_c36866240") ? 1.5 : 1;   // 冰晶擅御火焰
        const shieldPts = Math.min(l.cur, Math.ceil(left / eff));     // 消耗的护罩点数
        const cover = Math.min(left, shieldPts * eff);                // 实际抵消的伤害
        l.cur = Math.max(0, l.cur - shieldPts);
        left = Math.max(0, left - cover);
        absorbed += cover;
      }
      // 耗尽的一次性层移除；可充能层 cur=0 保留（回主神充能）
      p.shields = p.shields.filter(l => l.cur > 0 || l.rechargeable);
      return { dmg:left, absorbed:Math.round(absorbed) };
    },
    /* 回主神全身修复：把所有可充能护盾充满；返回充满的层数 */
    recharge(){
      const p = WK.P; if (!p || !Array.isArray(p.shields)) return 0;
      let n = 0;
      p.shields.forEach(l => { if (l.rechargeable && l.cur < l.max){ l.cur = l.max; n++; } });
      return n;
    }
  };

  /* ===== 豆包v169：传说魔法类专属归类 =====================================
     大表 637 条的 kind 噪声很大：召唤「模型」被标 weapon/shield/arrow、寒冰箭法杖被塞进
     arrow、56 张符全标 accessory、射影机自成 film。盲信 kind 会买一堆穿不上/不能用的东西。
     这里按「名称 + stats」二次归类，目标：绝大部分魔法兑换【买到即可穿 / 即可用】。
       · 实体法器/兵器（含从 misc 白名单捞回的 DOTA 系爪/手套/矛/扇/伞/宝珠等）→ 可装备，
         且武器的【普通攻击视为魔法攻击】(magicWeapon)，能打伤物理免疫的鬼怪；
       · 卷轴 scroll → 战斗主动法术（攻击 / 结界治疗），一发一耗；
       · 丹药/粉尘/真视药水 consumable → 战斗内回复或临时增益（真视 / 给武器临时附魔）；
         纯修行向（塑丹/筑基/轮回…）本集无修行体系，给可点击说明桩、不吞道具；
       · 护身符 charm → 沿用 v167（佩戴加 maxHp 等 / 战斗主动驱邪）；
       · 射影机 → 可装备的对灵 ranged 魔法「相机」，普攻即魔法；胶卷持有即可；
       · 召唤「模型」/ 传送 / 隐身 / 乾坤袋储物 / 魔法书抄录 → 数值先落地可穿戴，
         真正的召唤援军 / 传送 / 抄录机制留 TODO 桩，待后续恐怖片与技能系统开放。 */
  WK.magicEquipGuess = function (it) {
    const n = it.name || "";
    // 排除：召唤物、消耗品、书卷、胶卷、空间法宝、纯符咒（这些走专门分支，不当实体装备）
    if (/模型|召唤|分身|附体|变身|卷轴|药水|粉尘|胶卷|射影机|乾坤|魔法书|丹$|符$|神行符|结界/.test(n)) return null;
    if (/(剑|刀|杖|矛|斧|锤|鞭|爪|刃|刺|匕首|扇|伞|枪)$|之爪|手套$|长枪$/.test(n))
      return { kind: "weapon", slot: "weapon", wepType: "melee" };
    if (/(铠|甲|袍|风衣|衣)$|圆环$|皇冠?$/.test(n))
      return { kind: "armor", slot: "armor" };
    if (/(戒|指环|项链|宝珠|念珠|珠|玉|坠|护符|徽章|纹章)$/.test(n))
      return { kind: "equip", slot: "accessory" };
    return null;
  };

  WK.magicFinish = function (it, def) {
    const n = it.name || "";
    const price = Number(it.price) || 0;

    // —— A. 召唤系「模型」：数值当实体装备先用；真正召唤 100 个援军的机制留桩 ——
    if (/模型|召唤/.test(n)) {
      def.summon = true; def.bind = "equip";
      // TODO(后续恐怖片/技能系统)：消耗后召唤对应兵种 NPC 援军参战、持续 72h；现阶段只取装备数值。
      if (!def.slot) {   // 弓箭手/轻骑兵/刺客模型被错分成 arrow/misc：补成可手持法器
        it.equip = true; it.slot = "weapon"; it.wepType = "melee";
        def.kind = "weapon"; def.slot = "weapon"; def.wepType = "melee";
        if (!def.stats) { def.stats = WK.deriveEquipStats("melee", it); def.derived = true; }
      }
    }

    // —— B. 法杖 / 寒冰箭法杖（被错塞进 arrow）：归魔法近战法器 ——
    if (/(杖|法器)/.test(n) && def.kind !== "weapon") {
      it.equip = true; it.slot = "weapon"; it.wepType = "melee"; delete it.ammoTag;
      def.kind = "weapon"; def.bind = "equip"; def.slot = "weapon"; def.wepType = "melee";
      delete def.ammoTag;
      if (!def.stats) { def.stats = WK.deriveEquipStats("melee", it); def.derived = true; }
    }

    // —— C. 射影机=对灵 ranged 魔法武器；各式胶卷持有即可（07/零式无限），威力差异留桩 ——
    if (it.kind === "film") {
      if (/射影机|相机/.test(n)) {
        // 远程魔法武器：wepType=ranged 即可走远程伤害区间/hasRangedWeapon，不必打 type=firearm
        // （it 是 CATALOG 目录原引用，写 type=firearm 会让商店角标误显示「枪械」）。
        it.equip = true; it.slot = "weapon"; it.wepType = "ranged"; delete it.type;
        def.kind = "weapon"; def.bind = "equip"; def.slot = "weapon"; def.wepType = "ranged"; delete def.type;
        def.film = true;
        if (!def.stats) def.stats = WK.deriveEquipStats("ranged", it);
        // TODO(咒怨卷)：不同胶卷(14/60/90/零式)作为射影机的特殊弹，分别给克制/伤害档位。
      } else {
        def.kind = "misc"; def.bind = "item"; def.filmRoll = true;
        if (/07式|零式/.test(n)) def.infinite = true;
        def.desc = (def.desc || "") + "（装入射影机使用；现阶段持有即可，相机的超自然攻击不另计胶卷消耗）";
      }
    }

    // —— D. misc 里的实体法器/兵器/防具/饰品捞回可装备（数据驱动，约 20+ 件）——
    if (!it.equip && it.kind === "misc") {
      const g = WK.magicEquipGuess(it);
      if (g) {
        it.equip = true; it.slot = g.slot; if (g.wepType) it.wepType = g.wepType;
        def.kind = g.kind; def.bind = "equip"; def.slot = g.slot; if (g.wepType) def.wepType = g.wepType;
        if (!def.stats) {
          const sk = g.kind === "armor" ? "armor" : (g.wepType === "ranged" ? "ranged" : "melee");
          def.stats = WK.deriveEquipStats(sk, it); def.derived = true;
        }
      }
    }

    // —— E. 一切魔法兵器：普攻视为魔法攻击（ghost 也吃）；本集血肉怪物理魔法皆吃，无副作用 ——
    if (def.kind === "weapon") def.magicWeapon = true;

    // —— F. 卷轴：战斗主动法术（伤害取 scrollDmg/spellPower；结界守护类=治疗）——
    if (def.kind === "scroll") {
      def.magicScroll = true; def.battleUse = true;
      const st = it.stats || {};
      def.scrollDmg = Math.max(20, Math.round(Number(st.scrollDmg || st.spellPower || price * 0.6)));
      if (/结界|守护|治愈|治疗|恢复|圣愈|庇护/.test(n)) {
        def.scrollHeal = true; def.kind = "heal";
        def.heal = { flatHp: def.scrollDmg };   // 复用统一回复链路（战斗/非战皆可）
      }
    }

    // —— G. 丹药 / 粉尘 / 真视药水：回复 or 临时增益；纯修行向给说明桩 ——
    if (it.kind === "consumable") {
      if (/九转还魂|回魂丹|续命丹|锻体丹|避毒丹/.test(n)) {
        const big = /九转还魂/.test(n);
        def.kind = "heal"; def.bind = "item"; def.battleUse = true; def.consumable = true;
        def.heal = { flatHp: big ? Math.round(500 + price) : Math.round(80 + price * 0.5) };
      } else if (/精元丹|静心丹|黄芽丹|调和丹/.test(n)) {
        def.kind = "heal"; def.bind = "item"; def.battleUse = true; def.consumable = true;
        def.heal = { flatSta: Math.round(40 + price * 0.4) };
      } else if (/真视/.test(n)) {
        def.kind = "battle"; def.bind = "item"; def.battleUse = true; def.consumable = true; def.buffKind = "sight";
      } else if (/附魔粉尘/.test(n)) {
        def.kind = "battle"; def.bind = "item"; def.battleUse = true; def.consumable = true; def.buffKind = "enchant";
      } else {
        // 塑丹/筑基/三元归一/轮回/绝道/封阳/仙境丹 等：本集无道士修行体系，给说明、不吞道具
        def.kind = "misc"; def.bind = "item"; def.cultivate = true;
      }
    }

    // —— H. 魔法书：抄录 / 学习桩（真正的法术抄录随魔法技能体系开放）——
    if (it.kind === "book") { def.kind = "misc"; def.bind = "item"; def.study = true; }

    // —— I. 一次性护身符兜底（v167 主流程已设，双保险）——
    if (def.kind === "charm") def.disposable = /一次性/.test(n);
  };

