  /* gate 门控：怪不是一开始就在的，红后关闭后它们才脱困（对齐原著） */
  WK.SPAWN_GATES = {
    redqueenOff: { label:"关闭火焰女皇之后", test:f => !!(f && f.redqueenOff) },
    routeB:      { label:"B线·进入下水道后", test:f => !!(f && f.routeB) },
    crawlerAtk:  { label:"爬行者攻门剧情时", test:f => !!(f && f.crawlerAttack) }
  };

  /* —— 区域默认规则：[怪id 池] / 每波数量区间 / 清场后冷却ms / 同场波数上限 / gate —— */
  WK.SPAWN_ZONES = {
    lab:     { pool:["zombie","zombie","zombie_sci"], range:[4,8], cooldown:20000, cap:1, gate:"redqueenOff" },
    dining:  { pool:["zombie","zombie","zombie_sci"], range:[5,9], cooldown:18000, cap:1, gate:"redqueenOff" },
    control: { pool:["zombie","zombie_sci"],          range:[3,6], cooldown:25000, cap:1, gate:"redqueenOff" },
    sewer:   { pool:["zombie","zombie_sci"],          range:[3,6], cooldown:22000, cap:1, gate:"routeB" },
    /* 豆包v138 N19：蜂房后勤三片——维护区（少量丧尸）、犬舍区（丧尸犬群）、员工宿舍区（丧尸+搜刮）*/
    maint:   { pool:["zombie","zombie_sci"],          range:[3,6], cooldown:24000, cap:1, gate:"redqueenOff" },
    kennel:  { pool:["zombie_dog"],                   range:[3,6], cooldown:20000, cap:1, gate:"redqueenOff" },
    dorm:    { pool:["zombie","zombie","zombie_sci"], range:[3,7], cooldown:22000, cap:1, gate:"redqueenOff" }
    // train_in / platform / stairwell / laser / core（默认）/ train_back / godspace：无默认刷怪（剧情点在 SP_ROOMS 单独配置）
  };

  /* —— 特殊房间覆盖：省略字段回落到区域默认；pool/range/cooldown/cap/gate 均可单写 —— */
  WK.SPAWN_ROOMS = {
    /* 红后锁着的房间：开门即是「守卫群」，群更大、可反复刷，兼具体验与刷点用途 */
    l_tank_a:   { range:[5,9],  cooldown:30000 },
    l_tank_b:   { range:[5,9],  cooldown:30000 },
    l_office:   { range:[6,10], cooldown:30000 },
    l_storage:  { range:[6,10], cooldown:30000 },
    l_armory:   { silent:true },   // 豆包v134：一级卡门后的纯物资房，不刷怪
    /* 豆包v137 N18：安保簇（监控间/保养室/保险库）全 silent 纯物资；
       BOW 实验簇关红后后在丧尸群里高概率混爬行者（越深处越凶），主任样本库 silent、奖励靠三级门把关 */
    l_sec_a:    { silent:true },
    l_sec_b:    { silent:true },
    l_vault:    { silent:true },
    l_bow_a:    { range:[4,7], cooldown:28000, crawlerChance:0.22 },
    l_bow_b:    { range:[4,7], cooldown:28000, crawlerChance:0.26 },
    l_bio_vault:{ silent:true },
    /* 豆包v138 N19：后勤三片里的纯物资/到头房静音；犬舍跑道与犬舍主间刷狗（走 kennel 区默认）*/
    m_plant:    { silent:true },    // 设备机房：纯工具/物资
    k_surgery:  { silent:true },    // 动物手术室：关门后纯物资
    dorm_kitchen:{ silent:true },   // 员工餐厅/厨房：纯搜刮
    c_corridor: { range:[5,8],  cooldown:30000 },
    core_supply:{ range:[4,7],  cooldown:30000 },
    /* v132/v136：集装箱仓储厅（d_containers 西厅 + d_w1/d_w2/d_e1/d_e2 四个隔间）一律 silent，
       不随机刷丧尸，威胁只来自「玩家主动开箱」放出的爬行者，保证仓储区是搜刮节奏而非连环野战；
       普通丧尸仍在通道房（d_entry/d_floor/d_side/d_gate）按 dining 默认规则刷。*/
    d_containers:{ silent:true },
    d_w1:        { silent:true },
    d_w2:        { silent:true },
    d_e1:        { silent:true },
    d_e2:        { silent:true },
    d_floor:     { crawlerChance:0.18, cooldown:22000 },   // 群波中 18% 额外混入 1 只爬行者
    d_side:      { crawlerChance:0.12, cooldown:22000 },
    /* B 线：半空通道爬行者自上而下猎杀；返程列车上的爬行者（雷恩尸变那段）*/
    sw_walkway:  { pool:["crawler"], range:[1,1], cooldown:60000, cap:1, gate:"routeB" },
    tb_train:    { pool:["crawler"], range:[1,1], cooldown:900000, cap:1, gate:"routeB" },
    /* A 线死守主机房：剧情里两只爬行者攻门（N12 触发，非刷点场，冷却极长）*/
    /* A 线最终战：两只爬行者沿唯一激光通道攻向防护门（N12 特殊战斗，死亡亦可回归）*/
    core_door:   { pool:["crawler"], range:[2,2], cooldown:900000, cap:1, gate:"crawlerAtk" }
  };

  /* 合并某房间最终生效规则：房间覆盖 > 区域默认 > 无怪 */
  WK.Spawner = {
    ruleFor(roomId) {
      const r = WK.ROOMS[roomId];
      if (!r) return null;
      const base = WK.SPAWN_ZONES[r.zone];
      const over = WK.SPAWN_ROOMS[roomId];
      if (!base && !over) return null;
      const rule = Object.assign({}, base || null, over || null);
      rule.room = roomId;
      return rule;
    },
    gateOpen(rule, flags) {
      if (!rule.gate) return true;
      const g = WK.SPAWN_GATES[rule.gate];
      return g ? g.test(flags || {}) : false;
    },
    _rand(lo, hi) { return lo + Math.floor(Math.random() * (hi - lo + 1)); },
    /* 摇出当前房间此刻的怪波：gate 未开 → null；否则返回 {rule, wave:[{id,count}]} */
    roll(roomId, flags) {
      const rule = this.ruleFor(roomId);
      if (!rule) return null;
      if (rule.silent) return null;   // 豆包v134：纯物资/剧情房显式静音，永不摇怪
      if (!this.gateOpen(rule, flags)) return { rule:rule, open:false, wave:[] };
      const wave = [];
      const pool = rule.pool || ["zombie"];
      const pick = pool[Math.floor(Math.random() * pool.length)];
      // pool 里若全是 crawler（爬行者点），直接按 range 出爬行者，不再叠丧尸群
      if (pool.every(x => x === "crawler")) {
        wave.push({ id:"crawler", count:this._rand(rule.range[0], rule.range[1]) });
      } else {
        const zId = pick;
        wave.push({ id:zId, count:this._rand(rule.range[0], rule.range[1]) });
        if (rule.crawlerChance && Math.random() < rule.crawlerChance) wave.push({ id:"crawler", count:1 });
      }
      return { rule:rule, open:true, wave:wave };
    },
    /* N6 战斗接入位（本阶段空实现/预留）：清场后设置冷却，冷却内不再刷 */
    markCleared(roomId) {
      const rule = this.ruleFor(roomId);
      if (!rule || !WK.P.spawns) return;
      const now = Date.now();
      WK.P.spawns[roomId] = { lastClear:now, cooldownUntil:now + (rule.cooldown || 20000) };
    },
    inCooldown(roomId) {
      const s = WK.P && WK.P.spawns && WK.P.spawns[roomId];
      return !!(s && Date.now() < s.cooldownUntil);
    }
  };

  /* ============================================================
   * 豆包v128：场景互动点 WK.SPOTS（配置驱动，专治「地图太空、没东西可点」）
   * ------------------------------------------------------------
   * 想给任意房间加可互动物，只需在 LIST[roomId] 里补一个 spot：
   *   { id:"唯一id", title:"卡片标题", desc:"说明文字", btn:"按钮文字",
   *     danger:true,                       // 可选：红框高危样式（精英怪/赌命）
   *     show(p){ return 布尔; },            // 可选：何时出现（旗标/阶段/是否一次性）
   *     run(p){ ... } }                     // 点击后执行（开战/拿道具/弹窗均可）
   * 一次性点位用 p.flags._xxx 锁；刷怪点位直接复用 WK.Spawner 的冷却。
   * 卡片渲染在九宫格正下方、人物列表上方（#spot-banner）。
   * ============================================================ */
  WK.SPOTS = {
    LIST: {
      /* ===== 主神空间（v209：敲门逻辑加到canExit，NPC交谈用现有头像系统，不做新SPOT） ===== */

      /* 豆包v129：T病毒原液/血清已移至列车车厢内的可搜刮物件（WK.OBJ），
         开场苏醒即可在车厢里翻出；站台不再放重复药剂。 */

      /* 豆包v132：B餐厅集装箱阵列改为 WK.OBJ 里一排独立集装箱卡片（见 WK.OBJ.OBJECTS.d_containers），
         不再用单个大金色窗口。红后关前：能凑近看、能「手欠去开」，但张杰在附近会喝止；
         红后关后的逐箱开箱/爬行者战斗在 N17 细化。 */

      /* —— 餐厅侧廊：原本只有刮痕的空房间，给一个一次性搜刮点（血清或藏着的爬行者，二选一）—— */
      d_side: [{
        id:"side_locker",
        title:"刮痕尽头的维修柜",
        desc:"粗重刮痕一直拖到一只虚掩的铁皮维修柜前。柜门被什么东西从里面顶开了一条缝，黑黢黢的看不清。",
        btn:"拉开维修柜",
        danger:true,
        show:p => !!p.flags.redqueenOff && !p.flags._sideLocker,
        run(){
          const p = WK.P;
          p.flags._sideLocker = true; WK.save.write(); WK.renderScene();
          if (Math.random() < 0.5) {
            p.items = p.items || {};
            p.items.antiviral = (p.items.antiviral || 0) + 1; WK.save.write();
            WK.ui.generic("维修柜里的急救盒",
              '<div style="line-height:1.9;color:#c8d6c8;">你猛地拉开柜门——里面没有活物，只有一个落灰的急救盒。<br>' +
              '盒中静静躺着 <span style="color:#7fd18a;">一支抗病毒血清</span>。你长出了一口气，把它收进怀里。</div>' +
              '<button class="here-btn primary" style="width:100%;margin-top:14px;padding:11px;" onclick="WK.ui.closeOverlay(\'ov-generic\')">收下</button>');
          } else {
            WK.ui.generic("柜子里有东西！",
              '<div style="line-height:1.9;color:#c8d6c8;">柜门拉开的一瞬，一道湿漉漉的赤红色影子贴着地面扑出——是一只顺着气味钻进柜子、把这里当成窝的<span style="color:#e0a0a0;">爬行者</span>！</div>' +
              '<button class="here-btn primary" style="width:100%;margin-top:14px;padding:11px;" onclick="WK.ui.closeOverlay(\'ov-generic\');WK.battle.start(\'d_side\',{wave:[{id:\'crawler\',count:1}],title:\'侧廊 · 柜中爬行者\',noFlee:false,onWin:function(){WK.Spawner.markCleared(\'d_side\');WK.renderScene();}})">迎战 / 撤离</button>');
          }
        }
      }]
    },

    forRoom(roomId){ return this.LIST[roomId] || []; },
    act(roomId, id){
      const spot = this.forRoom(roomId).find(s => s.id === id);
      if (!spot) return;
      if (spot.show && !spot.show(WK.P)) return;   // 二次校验，防止过期 DOM 误触
      spot.run(WK.P);
    },
    render(r){
      const el = document.getElementById("spot-banner");
      if (!el || !WK.P) return;
      // 房间对象字面量不带 id，房间号统一取玩家当前位置（r 仅用于其他渲染，这里不依赖 r.id）
      const roomId = WK.P.location;
      const spots = this.forRoom(roomId).filter(s => !s.show || s.show(WK.P));
      if (!spots.length) { el.innerHTML = ""; return; }
      el.innerHTML = spots.map(s => {
        const bd = s.danger ? "border-color:#8a4a3a;background:rgba(190,90,60,.08);"
                           : "border-color:var(--gold);background:rgba(216,177,90,.07);";
        const tc = s.danger ? "#e0a0a0" : "var(--gold)";
        return '<div style="margin-top:12px;border:1px solid;border-radius:12px;padding:13px 14px;' + bd + '">' +
          '<div style="font-size:13px;font-weight:bold;margin-bottom:6px;color:' + tc + ';">' + s.title + '</div>' +
          '<div style="font-size:13px;color:var(--dim2);line-height:1.7;margin-bottom:11px;">' + s.desc + '</div>' +
          '<button class="here-btn ' + (s.danger ? "" : "primary") + '" style="width:100%;" ' +
            'onclick="WK.SPOTS.act(\'' + roomId + '\',\'' + s.id + '\')">' + s.btn + '</button>' +
        '</div>';
      }).join("");
    }
  };

  /* ============================================================
   * 豆包v129：场景物件系统 WK.OBJ（箱 / 柜 / 架 / 尸体 / 终端，逐个卡片可搜刮）
   * ------------------------------------------------------------
   * 设计：像 NPC 一样，把房间里能翻的东西数据化成卡片，渲染在九宫格下方。
   *   OBJECTS[roomId] = [ obj, ... ]
   *   obj 字段：
   *     id 唯一；name 卡片名；ava 单字图标；kind 仅作图标底色；
   *     desc 未搜时的说明；openText 搜开时的场景描写（可选）；
   *     show(p) 可选显示门控；frozen(p) 返回 true=被封冻/锁住、暂时打不开（只给反馈）；
   *     danger 红框（暗示有风险，如军械/有怪）；
   *     drops:[{id:ITEM_DEF键, n:数量}] 直接掉落；
   *     fight:{wave,title,noFlee} 开箱先触发战斗，打赢才给 drops（供 N17/N18 集装箱、装死尸体）；
   *     info:{title,html} 纯情报/文件（读完即视为搜查过）。
   *   状态写 P.objState["房|id"]：
   *     undefined 未搜；"done" 已搜空；{remain:[{id,n}]} 开过但背包放不下、物资留存（腾格后可再取）。
   *   容量走 WK.inv：关键道具(bulk0)必收下，占格物按剩余容量取舍，绝不静默吞物资。
   * ============================================================ */

  /* 豆包v132：B餐厅冷冻集装箱构造器。一排外形一致的金属箱，卡片只写「集装箱」+编号，
     不剧透里面是什么。红后关前：能看、能「手欠去开」，但张杰在附近会喝止、不在也撬不开（低温电子锁）；
     红后关后：逐箱可真正开启，按该箱 crateChance（缺省回落 RULES.crateCrawlerChance）摇出爬行者或普通物资（第一部偏稳，概率可调）。
     v136 N17：工厂支持批量生成与「每房间独立出怪率」——越靠仓储深处的隔间，爬行者概率越高。*/
  function crateObj(id, chance){
    return {
      id:id, ava:"箱", name:"集装箱", crate:true,
      no:id.slice(-2),
      crateChance:(chance == null ? null : chance),   // 该箱开出爬行者的概率；null=用全局 RULES
      desc:"一人多高的金属集装箱，表面结着一层薄霜，观察缝里黑漆漆的，看不清里面。"
    };
  }
  /* 批量造一排集装箱：crateRow(7) → [crate_01 … crate_07]；objState 以「房间|id」隔离，故各房可复用同一组 id 而不冲突 */
  function crateRow(n, chance){
    const arr = [];
    for (let i=1;i<=n;i++){
      const no = (i<10 ? "0"+i : ""+i);
      arr.push(crateObj("crate_"+no, chance));
    }
    return arr;
  }

